import React, { useState } from "react";
import { FaEnvelope, FaLock, FaEye, FaEyeSlash } from "react-icons/fa";
import { useNavigate } from "react-router-dom";
import Mughallogo from "../assets/Mughallogo.png";
import axios from "../Axios/Axios";
import "bootstrap/dist/css/bootstrap.min.css";

export default function Login({ onLogin }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const navigate = useNavigate();

  const [loading, setLoading] = useState(false); // Add this line at the top

  const handleLogin = async () => {
    if (!email || !password) {
      alert("Please enter both email and password");
      return;
    }

    setLoading(true); // Start loading

    try {
      const response = await axios.post("/api/admin/login", {
        username: email,
        password: password,
      });

      localStorage.setItem("mughalsLoggedIn", response.data.token);
      alert("Login successful!");
      onLogin();
      navigate("/home");

    } catch (error) {
      console.log(error);
      alert("Login failed. Please check your credentials.");
    } finally {
      setLoading(false); // Stop loading
    }
  };


  return (
    <div className="container-fluid vh-100 d-flex align-items-center justify-content-center bg-dark">
      <div className="row border w-100 shadow-lg rounded-4 overflow-hidden" style={{ maxWidth: "900px", backgroundColor: "#1e1e2f" }}>
        {/* Left side - Image */}
        <div className="col-md-6 d-none d-md-flex align-items-center justify-content-center p-0" style={{ backgroundColor: "#2c2c3e" }}>
          <img
            src={Mughallogo}
            alt="Logo"
            className="img-fluid"
            style={{ maxHeight: "300px" }}
          />
        </div>

        {/* Right side - Login form */}
        <div className="col-md-6 p-5 text-white">
          <h2 className="text-center mb-4 fw-bold" style={{ color: "#9f33ff" }}>
            Welcome Back
          </h2>

          <div className="form-group mb-4">
            <div className="input-group">
              <span className="input-group-text bg-transparent text-white border-secondary">
                <FaEnvelope />
              </span>
              <input
                type="email"
                className="form-control bg-transparent text-white border-secondary"
                placeholder="Email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
              />
            </div>
          </div>

          <div className="form-group mb-4">
            <div className="input-group position-relative">
              <span className="input-group-text bg-transparent text-white border-secondary">
                <FaLock />
              </span>
              <input
                type={showPassword ? "text" : "password"}
                className="form-control bg-transparent text-white border-secondary"
                placeholder="Password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />
              <span
                className="position-absolute end-0 me-3 top-50 translate-middle-y text-white"
                style={{ cursor: "pointer" }}
                onClick={() => setShowPassword(!showPassword)}
              >
                {showPassword ? <FaEyeSlash /> : <FaEye />}
              </span>
            </div>
          </div>

          <button
            onClick={handleLogin}
            className="btn w-100 mt-3 p-2 text-white fw-bold"
            style={{ backgroundColor: "#9f33ff", borderRadius: "30px" }}
            disabled={loading} // disable button while loading
          >
            {loading ? "Please Wait..." : "Login"} {/* change text */}
          </button>

        </div>
      </div>
    </div>
  );
}