import React from "react";
import { FaUsers, FaBoxes, FaHistory } from "react-icons/fa";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
} from "chart.js";
import { Line } from "react-chartjs-2";

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend
);

export default function Home() {
  const data = {
    labels: ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul"],
    datasets: [
      {
        label: "Customers",
        data: [65, 59, 80, 81, 56, 55, 40],
        borderColor: "#8e44ad",
        backgroundColor: "rgba(142, 68, 173, 0.15)",
        tension: 0.4,
        fill: true,
        pointRadius: 5,
        pointHoverRadius: 7,
        borderWidth: 3,
      },
      {
        label: "Materials",
        data: [28, 48, 40, 19, 86, 27, 90],
        borderColor: "#e74c3c",
        backgroundColor: "rgba(231, 76, 60, 0.15)",
        tension: 0.4,
        fill: true,
        pointRadius: 5,
        pointHoverRadius: 7,
        borderWidth: 3,
      },
    ],
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: "top",
        labels: { font: { size: 14 }, color: "#555" },
      },
      title: {
        display: true,
        text: "Customers & Materials Over Time",
        font: { size: 22, weight: "bold" },
        color: "#333",
      },
      tooltip: { mode: "index", intersect: false },
    },
    interaction: { mode: "nearest", axis: "x", intersect: false },
    scales: {
      y: {
        beginAtZero: true,
        grid: { color: "#eee" },
        ticks: { color: "#666", font: { size: 14 } },
      },
      x: {
        grid: { color: "#eee" },
        ticks: { color: "#666", font: { size: 14 } },
      },
    },
  };

  return (
    <main className="dashboard-container">
      <header>
        <h1 className="dashboard-heading text-start" style={{color:'#9f33ff'}}>Dashboard Overview</h1>
      </header>

      <section className="card-grid">
        <article className="info-card">
          <div className="icon-circle purple">
            <FaUsers />
          </div>
          <div className="info-content">
            <h3>Customers</h3>
            <p>1,234</p>
          </div>
        </article>

        <article className="info-card">
          <div className="icon-circle red">
            <FaBoxes />
          </div>
          <div className="info-content">
            <h3>Materials</h3>
            <p>567</p>
          </div>
        </article>

        <article className="info-card">
          <div className="icon-circle orange">
            <FaHistory />
          </div>
          <div className="info-content">
            <h3>History</h3>
            <p>89 Records</p>
          </div>
        </article>
      </section>

      <section className="chart-section">
        <Line data={data} options={options} />
      </section>
    </main>
  );
}
