import React, { useState, useEffect } from "react";
import axios from "../Axios/Axios";
import { FaTimes } from "react-icons/fa";
import "bootstrap/dist/css/bootstrap.min.css";

export default function CustomerTable() {
  const [customers, setCustomers] = useState([]);
  const [modalData, setModalData] = useState(null);
  const [search, setSearch] = useState("");
  const [filterDate, setFilterDate] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const IMAGE_BASE_URL = `${axios.defaults.baseURL}/uploads/`;

  useEffect(() => {
    const mughalsLoggedIn = localStorage.getItem("mughalsLoggedIn");

    const fetchCustomers = async () => {
      try {
        setLoading(true);
        const res = await axios.get("/api/customers", {
          headers: {
            Authorization: `Bearer ${mughalsLoggedIn}`,
          },
        });
        setCustomers(res.data);
      } catch (err) {
        setError("Failed to fetch customer data.");
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    fetchCustomers();
  }, []);

  const openModal = (customer) => setModalData(customer);
  const closeModal = () => setModalData(null);

  const filteredCustomers = customers.filter((cust) => {
    const searchMatch =
      cust.name?.toLowerCase().includes(search.toLowerCase()) ||
      cust.NIC?.includes(search);

    const dateMatch = filterDate
      ? new Date(cust.createdAt).toISOString().split("T")[0] === filterDate
      : true;

    return searchMatch && dateMatch;
  });

  return (
    <div style={{ overflowX: "hidden" }}>
      <h1 className="text-start mb-4" style={{ color: "#9F33FF", fontSize: 28 }}>
        Customer List
      </h1>

      <div className="row mb-3 p-2">
        <div className="col-md-6 mb-2">
          <input
            type="text"
            placeholder="Search..."
            className="form-control rounded-5 p-2"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
        <div className="col-md-6 mb-2">
          <input
            type="date"
            className="form-control rounded-5 p-2"
            value={filterDate}
            onChange={(e) => setFilterDate(e.target.value)}
          />
        </div>
      </div>

      {loading && <p className="text-center">Loading...</p>}
      {error && <p className="text-danger text-center">{error}</p>}

      {!loading && !error && (
        <div className="table-responsive p-2">
          <table
            className="table table-hover"
          
          >
            <thead>
              <tr>
                <th className="py-3 px-4">Image</th>
                <th className="py-3 px-4">Name</th>
                <th className="py-3 px-4">CNIC</th>
                <th className="py-3 px-4">Created At</th>
                <th className="py-3 px-4">Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredCustomers.map((cust) => (
                <tr key={cust._id}>
                  <td className="align-middle py-3 px-4">
                    <img
                      src={
                        cust.image
                          ? `${IMAGE_BASE_URL}${cust.image}`
                          : "https://via.placeholder.com/50"
                      }
                      alt={cust.name}
                      style={{
                        width: 50,
                        height: 50,
                        borderRadius: "50%",
                        objectFit: "cover",
                      }}
                    />
                  </td>
                  <td className="align-middle py-3 px-4">{cust.name}</td>
                  <td className="align-middle py-3 px-4">{cust.NIC}</td>
                  <td className="align-middle py-3 px-4">
                    {new Date(cust.createdAt).toLocaleDateString()}
                  </td>
                  <td className="align-middle py-3 px-4">
                    <button
                      style={{
                        backgroundColor: "#9F33FF",
                        color: "#fff",
                        borderRadius: 8,
                        fontWeight: 600,
                        padding: "8px 14px",
                        border: "none",
                      }}
                      onClick={() => openModal(cust)}
                    >
                      View Details
                    </button>
                  </td>
                </tr>
              ))}
              {filteredCustomers.length === 0 && (
                <tr>
                  <td colSpan="5" className="text-center py-4">
                    No matching records found.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      {/* Modal */}
      {modalData && (
        <div
          className="modal fade show"
          style={{
            display: "flex",
            backgroundColor: "rgba(0,0,0,0.45)",
            position: "fixed",
            top: 0,
            left: 0,
            height: "100vh",
            justifyContent: "center",
            alignItems: "center",
            zIndex: 9999,
            padding: 20,
          }}
          onClick={closeModal}
        >
          <div
            className="bg-white rounded-3 p-4 position-relative"
            style={{
              maxWidth: 600,
              width: "100%",
              boxShadow: "0 5px 15px rgba(90, 42, 130, 0.4)",
              maxHeight: "90vh",
              overflowY: "auto",
              borderRadius: 18,
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <button
              onClick={closeModal}
              className="btn position-absolute"
              style={{ top: 18, right: 18, background: "none", border: "none" }}
            >
              <FaTimes size={22} color="#9F33FF" />
            </button>

            <div className="d-flex flex-column align-items-start gap-3" style={{ fontSize: 16 }}>
              <div className="text-center w-100">
                <img
                  src={
                    modalData.image
                      ? `${IMAGE_BASE_URL}${modalData.image}`
                      : "https://via.placeholder.com/100"
                  }
                  alt={modalData.name}
                  style={{
                    width: 100,
                    height: 100,
                    objectFit: "cover",
                    borderRadius: "50%",
                    marginBottom: 10,
                  }}
                />
              </div>

              <div className="w-100 p-3 rounded-2 bg-light">
                <strong>Name:</strong> {modalData.name}
              </div>
              <div className="w-100 p-3 rounded-2 bg-light">
                <strong>CNIC:</strong> {modalData.NIC}
              </div>
              <div className="w-100 p-3 rounded-2 bg-light">
                <strong>Created At:</strong>{" "}
                {new Date(modalData.createdAt).toLocaleDateString()}
              </div>
              <div className="w-100 p-3">
                <strong>Licenses:</strong>
                {modalData.licenses?.length > 0 ? (
                  <ul
                    className="mt-2"
                    style={{ paddingLeft: 20, color: "#9F33FF", fontWeight: 600 }}
                  >
                    {modalData.licenses.map((lic) => (
                      <li key={lic._id}>
                        {lic.licenseNumber} - Last Transaction:{" "}
                        {new Date(lic.lastTransactionDate).toLocaleDateString()}
                      </li>
                    ))}
                  </ul>
                ) : (
                  <p className="text-muted fst-italic">No licenses available</p>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}